    private final String currency;
    private final Map<String, Long> feesByScheme;

    public RateCard(String currency, Map<String, Long> feesByScheme) {
        this.currency = currency;
        this.feesByScheme = Map.copyOf(feesByScheme);   // our own unmodifiable copy
    }

    public String currency() { return currency; }
    public Map<String, Long> feesByScheme() { return feesByScheme; }   // safe to hand out
}

