public class IssuerConfigHolder {
    @Inject SettingsClient settingsClient;
    private IssuerConfig config = new IssuerConfig();   // 1. a mutable object in a plain field

    @Scheduled(every = "60s")
    void refresh() {                                   // scheduler thread
        Settings s = settingsClient.fetch();
        config.setBaseUrl(s.baseUrl());                // 2. changed in place...
        config.setTimeout(s.timeout());                // ...one field at a time
    }

    public IssuerConfig current() { return config; }   // 3. request threads read it
}

