public final class FeeSchedule {              // final: no mutable subclasses
    private final String currency;            // final fields: safe through a race
    private final List<Fee> fees;

    public FeeSchedule(String currency, List<Fee> fees) {
        this.currency = currency;
        this.fees = List.copyOf(fees);        // copy in: the caller can't change ours
    }

    public String currency() { return currency; }
    public List<Fee> fees() { return fees; }  // unmodifiable: safe to hand out
}

public final class FeeScheduleHolder {
    private volatile FeeSchedule current;     // volatile: each new schedule is published safely

    public void replace(FeeSchedule next) { current = next; }
    public FeeSchedule current() { return current; }
}

// Without the copy, the caller still holds the list and can change it under every reader.

