class FeeSchedule(val currency: String, fees: List<Fee>) {   // final by default
    val fees: List<Fee> = fees.toList()       // copy in: the caller can't change ours
}

class FeeScheduleHolder {
    @Volatile
    var current: FeeSchedule? = null          // each new schedule is published safely
        private set

    fun replace(next: FeeSchedule) { current = next }
}

// Without the copy, the caller still holds the list and can change it under every reader.
